			xml = Eventos.enviarEvento(config, xml, ServicosEnum.CCE, valida,true, DocumentoEnum.NFE);

			return XmlNfeUtil.xmlToObject(xml, TRetEnvEvento.class);

		} catch (JAXBException e) {
			throw new NfeException(e.getMessage(),e);
